#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, c;
    cin >> a >> b >> c;

    unordered_map<long long, int> cache;
    long long sum = 0;

    for (int i = 1; i <= a; ++i) {
        for (int j = 1; j <= b; ++j) {
            for (int k = 1; k <= c; ++k) {
                long long value = 1LL * i * j * k;
                auto it = cache.find(value);

                if (it != cache.end()) {
                    sum += it->second;
                    continue;
                }

                int divisors = 0;
                for (long long d = 1; d <= value / d; ++d) {
                    if (value % d == 0)
                        divisors += (d == value / d ? 1 : 2);
                }

                cache.emplace(value, divisors);
                sum += divisors;
            }
        }
    }

    cout << sum;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b, c;
    cin >> a >> b >> c;

    vector<long long> products;
    products.reserve(1LL * a * b * c);

    for (int i = 1; i <= a; ++i)
        for (int j = 1; j <= b; ++j)
            for (int k = 1; k <= c; ++k)
                products.push_back(1LL * i * j * k);

    sort(products.begin(), products.end());

    long long answer = 0;

    for (size_t p = 0; p < products.size();) {
        size_t q = p + 1;
        while (q < products.size() && products[q] == products[p])
            ++q;

        long long x = products[p];
        long long divisors = 0;

        for (long long i = 1; i <= x / i; ++i) {
            if (x % i == 0)
                divisors += (i == x / i ? 1 : 2);
        }

        answer += divisors * static_cast<long long>(q - p);
        p = q;
    }

    cout << answer;
    return 0;
}

